import{R as t,e as o,f as a,U as s}from"./chunks/framework.ywem4qy5.js";const h=JSON.parse('{"title":"Exporting","description":"","frontmatter":{},"headers":[],"relativePath":"submissions/exporting.md","filePath":"submissions/exporting.md","lastUpdated":1775908585000}'),r={name:"submissions/exporting.md"};function i(n,e,p,l,u,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h1><p>Exporting lets you take saved submission data out of Formie for reporting, transfer, or further processing.</p><h2 id="what-gets-exported" tabindex="-1">What gets exported <a class="header-anchor" href="#what-gets-exported" aria-label="Permalink to &quot;What gets exported&quot;">​</a></h2><p>Submission exports include both:</p><ul><li>built-in submission information, such as status and dates</li><li>the field values stored on the submission</li></ul><p>That makes exports useful for spreadsheets and reporting, not just for backup.</p><h2 id="what-to-expect-from-the-output" tabindex="-1">What to expect from the output <a class="header-anchor" href="#what-to-expect-from-the-output" aria-label="Permalink to &quot;What to expect from the output&quot;">​</a></h2><p>Formie prepares field values for export rather than dumping them exactly as they are stored internally.</p><p>That matters because some fields need to be flattened or expanded so the export is actually useful in a table format.</p><p>For example:</p><ul><li>simple fields may export as one column</li><li>complex fields may export as multiple columns</li><li>repeatable or nested content can expand to fit the export</li></ul><p>Exporting is useful when:</p><ul><li>a team needs a spreadsheet of submission data</li><li>you want to hand data to another system manually</li><li>you need a reporting snapshot outside Craft</li></ul><p>Submission export is about the saved records.</p><p>If you need to move the form structure itself, use <a href="/forms/import-export">Forms → Import &amp; Export</a> instead.</p>',15)])])}const f=t(r,[["render",i]]);export{h as __pageData,f as default};
